const mongoose = require('mongoose');

const employeeSchema = new mongoose.Schema(
  {
    username: {
      type: String,
      required: true,
      unique: true
    },

    password: {
      type: String,
      required: true
    },

    role: {
      type: String,
      enum: ['employee', 'admin'],
      default: 'employee'
    }
  },
  { timestamps: true }
);

module.exports = mongoose.model('Employee', employeeSchema);
